import type { StorybookConfig } from "@storybook/react-vite";

// Stories and docs pages live in stories/, outside packages/, so the library
// build never sees them. The docs and a11y addons render the autogenerated API
// docs and surface accessibility findings in the Storybook UI.
const config: StorybookConfig = {
  stories: [
    "../stories/**/*.mdx",
    "../stories/**/*.stories.@(js|jsx|mjs|ts|tsx)",
  ],
  addons: ["@storybook/addon-docs", "@storybook/addon-a11y"],
  framework: {
    name: "@storybook/react-vite",
    options: {},
  },
};

export default config;
